class Solution
{
    vector< vector< int >>ans;
    vector< int>path;
    void dfs(int n, int start)
    {
        for (int f = start; (long long) f*f <= n;++f)
        {
            if (n % f)
            {
                continue;
            }
            path.push_back(f);
            auto x = path;
            x.push_back(n / f);
            ans.push_back(x);
            dfs(n / f, f);
            path.pop_back();
        }
    }
public:
    vector< vector< int >>getFactors(int n)
    {
        dfs(n, 2);
        return ans;
    }
};
